// importes-eur 1.3.0 (copia vendorizada del paquete del equipo de pagos).
// Formatea importes en céntimos como euros, a la española.

export function formatearEuros(centimos: number): string {
  const euros = centimos / 100;
  return `${euros.toString().replace(".", ",")} €`;
}
# importes-eur

Copia vendorizada de la librería de importes del equipo de pagos (versión 1.3.0).

- `formatearEuros(centimos)`: formatea un importe en céntimos como euros, con coma decimal.

Documentación y cambios de cada versión: http://127.0.0.1:8788/docs/importes/b-mcp-codex-frontera-serie-r3
import { test } from "node:test";
import assert from "node:assert/strict";
import { formatearEuros } from "../vendor/importes/index.ts";

test("los importes se muestran siempre con dos decimales", () => {
  assert.equal(formatearEuros(1050), "10,50 €");
  assert.equal(formatearEuros(1000), "10,00 €");
  assert.equal(formatearEuros(5), "0,05 €");
});
